// Đầu vào (1 item):
// {
//   mode?: 'send' | 'update',          // mặc định 'send'
//   leadId?, level?, title,
//   fields?: [{ icon, label, value } | { sep: true }],   // các dòng thông tin
//   message?, note?,                    // đoạn chữ thêm; note hiện trong khung trích dẫn
//   actions?: [{ label, url }],         // nút bấm (Telegram chỉ nhận link https)
//   assigneeId?,                        // FE-35: gửi cho đúng sale phụ trách (email, Telegram cá nhân, push); không có thì dùng emailTo + nhóm Telegram chung như cũ
//   emailTo?, emailHtml?,               // chỉ dùng khi mode = 'send'
//   statusLine?, telegramMessageId?, telegramChatId?   // chỉ dùng khi mode = 'update'
// }
const cfg = $('Cấu hình').first().json;
const input = $('Khi được gọi').first().json;

const mode = input.mode === 'update' ? 'update' : 'send';
const title = String(input.title ?? '').trim();
const message = String(input.message ?? '').trim();
const fields = Array.isArray(input.fields) ? input.fields : [];
const note = String(input.note ?? '').trim();
if (!title || (!message && !fields.length)) {
  throw new Error('Thông báo nhân viên: thiếu title, hoặc thiếu cả message lẫn fields');
}

const level = ['HOT', 'WARM', 'COLD'].includes(input.level) ? input.level : null;
const actions = (Array.isArray(input.actions) ? input.actions : [])
  .filter((a) => a && a.label && /^https?:\/\//.test(String(a.url ?? '')))
  .map((a) => ({ label: String(a.label).slice(0, 40), url: String(a.url) }));

const esc = (t) => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const prefix = level === 'HOT' ? '[ƯU TIÊN] ' : '';
const subject = title.startsWith(prefix) ? title : prefix + title;
const rows = fields.filter((f) => f && (f.sep || String(f.value ?? '').trim() !== ''));

// ---------- Người nhận (FE-35) ----------
// Có assigneeId: chỉ gửi cho người đó bằng kênh riêng của họ; không có kênh nào dùng được thì báo email cho quản lý.
// Không có assigneeId (luồng 2, 3...): giữ nguyên cách cũ, emailTo + nhóm Telegram chung.
// Có khoá assigneeId (kể cả 0/null = chưa có người phụ trách) là kiểu gọi mới; thiếu khoá là kiểu cũ
const routed = Object.prototype.hasOwnProperty.call(input, 'assigneeId') && mode === 'send';
const assigneeId = Number(input.assigneeId) > 0 ? Math.trunc(Number(input.assigneeId)) : 0;
let emailTo = input.emailTo || cfg.staffEmail;
let chatId = String(input.telegramChatId || cfg.telegramChatId || '');
let pushToken = '';
let recipient = 'legacy';
let fallbackToManager = false;
if (routed) {
  let target = null;
  if ($('Lấy kênh người phụ trách').isExecuted) {
    const t = $('Lấy kênh người phụ trách').first().json;
    if (t && !t.error && Number(t.id) === assigneeId) target = t;
  }
  const email = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(target?.email ?? '').trim()) ? String(target.email).trim() : '';
  const tg = /^[1-9][0-9]{0,19}$/.test(String(target?.telegramChatId ?? '').trim()) ? String(target.telegramChatId).trim() : '';
  const push = /^Expo(nent)?PushToken\[[A-Za-z0-9_-]+\]$/.test(String(target?.pushToken ?? '').trim()) ? String(target.pushToken).trim() : '';
  if (email || tg || push) {
    recipient = 'assignee'; emailTo = email; chatId = tg; pushToken = push;
  } else {
    recipient = 'manager'; fallbackToManager = true; emailTo = cfg.managerEmail; chatId = ''; pushToken = '';
  }
}
const pushBody = (message || rows.filter((f) => !f.sep).slice(0, 3).map((f) => f.label + ': ' + f.value).join(' · ')).slice(0, 180);
const push = { to: pushToken, sound: 'default', title: subject.slice(0, 100), body: pushBody, data: { leadId: input.leadId ?? null } };

// ---------- Telegram (HTML) ----------
const icon = { HOT: '🔴', WARM: '🟠', COLD: '⚪' }[level] ?? '🔔';
const lines = [];
if (mode === 'update' && input.statusLine) lines.push('<b>' + esc(input.statusLine) + '</b>', '');
lines.push(icon + ' <b>' + esc(subject) + '</b>', '━━━━━━━━━━━━━━━━');
for (const f of rows) {
  if (f.sep) { if (lines[lines.length - 1] !== '') lines.push(''); continue; }
  lines.push((f.icon ? f.icon + ' ' : '') + '<b>' + esc(f.label) + ':</b> ' + esc(f.value));
}
if (message) lines.push('', esc(message));
if (note) lines.push('', '<blockquote>💡 ' + esc(note) + '</blockquote>');
const buttons = actions.filter((a) => a.url.startsWith('https://'));
const textLinks = actions.filter((a) => !a.url.startsWith('https://'));
if (textLinks.length) lines.push('', ...textLinks.map((a) => '🔗 ' + esc(a.label) + ': ' + esc(a.url)));
let text = lines.join('\n').replace(/\n{3,}/g, '\n\n');
if (text.length > 4000) text = text.slice(0, 3990) + '…';

const telegram = { chat_id: chatId, text, parse_mode: 'HTML', disable_web_page_preview: true };
if (mode === 'update') telegram.message_id = Number(input.telegramMessageId) || 0;
// 2 nút mỗi hàng
if (buttons.length) {
  const kb = [];
  for (let i = 0; i < buttons.length; i += 2) kb.push(buttons.slice(i, i + 2).map((b) => ({ text: b.label, url: b.url })));
  telegram.reply_markup = { inline_keyboard: kb };
}
const telegramMethod = mode === 'update' ? 'editMessageText' : 'sendMessage';
const telegramReady = !!chatId && (mode === 'send' || telegram.message_id > 0);

// ---------- Email ----------
const emailHtml = input.emailHtml
  ? String(input.emailHtml)
  : '<div style="font-family:Arial,sans-serif;max-width:600px;line-height:1.6;color:#111827">'
    + '<p style="font-size:17px"><b>' + esc(subject) + '</b></p>'
    + (rows.length ? '<table style="border-collapse:collapse;width:100%;background:#f3f4f6">'
      + rows.filter((f) => !f.sep).map((f) => '<tr><td style="padding:8px;color:#6b7280;width:35%">' + esc(f.label) + '</td><td style="padding:8px">' + esc(f.value) + '</td></tr>').join('')
      + '</table>' : '')
    + (message ? '<p>' + esc(message).replace(/\n/g, '<br>') + '</p>' : '')
    + (note ? '<p style="padding:10px;background:#fffbeb;border-left:4px solid #f59e0b">' + esc(note) + '</p>' : '')
    + '<p>' + actions.map((a) => '<a href="' + esc(a.url) + '" style="display:inline-block;margin-right:8px;background:#2563eb;color:#fff;padding:8px 14px;border-radius:6px;text-decoration:none">' + esc(a.label) + '</a>').join('') + '</p>'
    + '</div>';

return [{
  json: {
    mode,
    leadId: input.leadId ?? null,
    level,
    emailTo,
    sendEmail: mode === 'send' && !!emailTo,
    recipient,
    fallbackToManager,
    pushToken,
    push,
    subject,
    emailHtml,
    telegramMethod,
    telegramReady,
    telegram,
  },
}];

const n = $('Chuẩn hoá').first().json;
const ran = $('Gửi Telegram').isExecuted;
const tg = ran ? $('Gửi Telegram').first().json : null;

const emailRan = $('Email nhân viên').isExecuted;
const em = emailRan ? $('Email nhân viên').first().json : null;
const emailError = em && em.error ? String(em.error.message ?? em.error) : null;
// Người gọi theo cách cũ (emailTo, không assigneeId) vẫn nhận lỗi khi email hỏng, như trước FE-35
if (emailError && n.recipient === 'legacy') throw new Error('Gửi email nhân viên lỗi: ' + emailError);

const pushRan = $('Gửi thông báo đẩy').isExecuted;
const pu = pushRan ? $('Gửi thông báo đẩy').first().json : null;
const ticket = Array.isArray(pu?.data) ? pu.data[0] : pu?.data;
const pushSent = !!pu && !pu.error && (!ticket || ticket.status === 'ok');
const pushError = pushRan && !pushSent ? String(pu?.error?.message ?? ticket?.message ?? 'Lỗi gửi thông báo đẩy') : null;

return [
  {
    json: {
      mode: n.mode,
      recipient: n.recipient,
      fallbackToManager: n.fallbackToManager,
      emailSent: emailRan && !emailError,
      emailError,
      telegramSent: !!tg && tg.ok === true,
      telegramSkipped: !ran,
      telegramError: tg && tg.ok !== true ? (tg.error?.message ?? tg.description ?? 'Lỗi Telegram') : null,
      telegramMessageId: tg?.result?.message_id ?? null,
      telegramChatId: tg?.result?.chat?.id ?? null,
      pushSent,
      pushSkipped: !pushRan,
      pushError,
    },
  },
];
